-- 06-grab.sql
-- 本地 prod-split 真实演示 seed，仅供联调，不属于生产迁移。
-- target database: omni_grab


BEGIN;
DELETE FROM waitlist_offer WHERE id BETWEEN 989501 AND 989560;
DELETE FROM waitlist_entry WHERE id BETWEEN 989301 AND 989360;
DELETE FROM waitlist_allocation_log WHERE id BETWEEN 989601 AND 989650;
DELETE FROM grab_request WHERE id BETWEEN 989001 AND 989200;
ON CONFLICT (id) DO UPDATE SET status = EXCLUDED.status, fail_reason = EXCLUDED.fail_reason, progress_status = EXCLUDED.progress_status, progress_message = EXCLUDED.progress_message, updated_at = EXCLUDED.updated_at;

ON CONFLICT (id) DO UPDATE SET status = EXCLUDED.status, update_time = EXCLUDED.update_time;

ON CONFLICT (id) DO UPDATE SET status = EXCLUDED.status, update_time = EXCLUDED.update_time;

ON CONFLICT (id) DO UPDATE SET status = EXCLUDED.status, message = EXCLUDED.message;

SELECT setval('grab_request_id_seq', GREATEST(COALESCE((SELECT MAX(id) FROM grab_request), 1), 1), true);
SELECT setval('waitlist_entry_id_seq', GREATEST(COALESCE((SELECT MAX(id) FROM waitlist_entry), 1), 1), true);
SELECT setval('waitlist_offer_id_seq', GREATEST(COALESCE((SELECT MAX(id) FROM waitlist_offer), 1), 1), true);
COMMIT;
